import{_ as a,o as t,c as i,a5 as r}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"Download Material — Implementation Plan","description":"","frontmatter":{},"headers":[],"relativePath":"feature/repository/download-material/plan.md","filePath":"feature/repository/download-material/plan.md"}'),o={name:"feature/repository/download-material/plan.md"};function n(l,e,d,s,c,u){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="download-material-—-implementation-plan" tabindex="-1">Download Material — Implementation Plan <a class="header-anchor" href="#download-material-—-implementation-plan" aria-label="Permalink to &quot;Download Material — Implementation Plan&quot;">​</a></h1><p><strong>Input:</strong> spec.md/ticket05. <strong>Blocked by:</strong> Add private canonical/provider/lease và View list/detail. Update/Remove không blocker ticket, nhưng integration test revoke/delete phải chạy khi các FR đó land; vẫn tự fixture deleted/transition trước đó để verify contract. D1→D5.</p><h2 id="d1-—-service-contract-va-guard" tabindex="-1">D1 — Service contract và guard <a class="header-anchor" href="#d1-—-service-contract-va-guard" aria-label="Permalink to &quot;D1 — Service contract và guard&quot;">​</a></h2><p>Extend MaterialController/MaterialService bằng POST base/{id}/download, no request body, ApiResponse&lt;MaterialDownloadResponse&gt; record filename/mimeType/fileSize/downloadUrl/expiresAt. Frontend fileSize theo shared DTO convention; bytes từ immutable verified metadata và HEAD, không từ request. RequestId fallback, no-store; error response không chứa bucket/key.</p><p>Shared MaterialAccessPolicy: PG account/workspace path membership active/profiles, scoped material + effective root audience. OWNER no ops403; CLIENT mismatched404; ADMIN existing support scoped/audit. No quota reservation/usage read dependency trong read path; effective expired plan không chặn route trong SubscriptionRequestFilter. READY + deleted_at null + purge_state NONE + root access_state STABLE. Không copy parent or fallback url/provider; legacy chưa private-key verified trả unavailable/no signer.</p><h2 id="d2-—-head-race-ordering-va-signer" tabindex="-1">D2 — HEAD, race ordering và signer <a class="header-anchor" href="#d2-—-head-race-ordering-va-signer" aria-label="Permalink to &quot;D2 — HEAD, race ordering và signer&quot;">​</a></h2><p>Get provider/key stored immutable; key prefix allowlist/workspace validated, không URL parse từ browser. Adapter HEAD có timeout/retry bounded; missing409 storage_missing, provider403/ 429/5xx/timeout503 generic. Nếu HEAD size/MIME khác verified immutable material thì409 material unavailable+reconcile, không âm thầm đổi metadata hoặc tải object lạ.</p><p>Không giữ PG/Mongo transaction qua HEAD. Sau HEAD lấy short material/root lease/fence Add, reauthorize/re-read status/version/root revision mới nhất trước ký. Delete/revoke dùng cùng protocol; nếu trước acquire khác revision →retry read tối đa1 hoặc409, không unbounded loop. Sign trong critical section ngắn (credentials refresh preflight ngoài lock), no file bytes through Business. Nếu lease mất trước response fail503 và không trả signed URL.</p><p>FileStorageService overload options record (provider,key,TTL,disposition,type) reuse existing S3 clients/router; cũ createPresignedDownloadUrl(key) giữ Post/Publish behavior/TTL3600 nếu đang cần, không global đổi thành120. URL TTL min(120,credential remaining),expiresAt thực. Response signed GET attachment, RFC filename* UTF-8 plus safe ASCII fallback, trusted MIME, private/no-store overrides nếu provider hỗ trợ G0. Test actual HTTP không chỉ kiểm builder. Sanitize qua FilenamePolicy Add/Update; don&#39;t encode entire Content-Disposition twice. READY key immutable tránh HEAD/GET TOCTOU, provider có mutation outside app phải cảnh báo operationally; storage identity mismatch fail closed, không coi ACL PG là IAM protection.</p><h2 id="d3-—-audit-va-secret-handling" tabindex="-1">D3 — Audit và secret handling <a class="header-anchor" href="#d3-—-audit-va-secret-handling" aria-label="Permalink to &quot;D3 — Audit và secret handling&quot;">​</a></h2><p>Sau guard/sign trước trả URL ghi DOWNLOAD_LINK_ISSUED durable outbox/audit intent bằng shared Add mechanism operationId/requestId; không signed URL/signature/bucket credentials. Audit failure503 no response URL. Retry xin link có thể tạo event cấp link mới, không suy diễn one-time hoặc exactly-once download. Outbox duplicate consume giữ single AuditLog event. Release lease after intent+state check; request ordering linearized tại issuance, URL cũ sau revoke có thể dùng đến TTL. Không audit download completed/browser saved. API/gateway logging/APM mask query string storage URLs, body redaction for downloadUrl; không cache DTO signed URL trong Redis/localStorage/analytics/error tracker.</p><h2 id="d4-—-files-va-ui" tabindex="-1">D4 — Files và UI <a class="header-anchor" href="#d4-—-files-va-ui" aria-label="Permalink to &quot;D4 — Files và UI&quot;">​</a></h2><ul><li>Business existing MaterialController/Service/impl, FileStorageService/impl/options/config, shared access/lease/filename/audit, ErrorCode + proposed MaterialDownloadResponse record, SubscriptionRequestFilter allow download route, audit schema mapping reused.</li><li>Gateway existing protected route, logging redaction/correlation only khi cần; không route binary stream hoặc public exception cho download.</li><li>Web <code>src/services/materialService.ts</code>, <code>src/types/material.ts</code>, MediaTab/MediaDetailPanel, proposed useMaterialDownload feature hook, shared API client; no axios auth to storage.</li><li>Locales <strong><code>src/i18n/locales/vi/library.json</code> + <code>en/library.json</code></strong>, keys repository.download/ preparingDownload/downloadStarted/downloadFailed/storageMissing/linkExpired/ switchWorkspaceCancelled/unavailable; reuse equivalent keys thay duplicate texts.</li></ul><p>Hook capture workspace/material/request generation, disable button during link request, abort on unmount/switch and ignore stale response even if fetch abort race. Browser anchor/ navigation direct URL (attachment header quyết định download, không rely HTML download cross-origin). Không <code>_blank</code> auth token, không fetch entire blob. Button accessible name, aria-busy, state pending/retry,error≥5s; toast “Đã bắt đầu tải xuống”, no percent giả khi chỉ navigation. Không hứa tự bắt được storage-expired navigation; bấm lại xin fresh link. Vi/en, theme/light/dark, keyboard/responsive. Quota lock banner không disable Download.</p><h2 id="d5-—-verification-va-rollout" tabindex="-1">D5 — Verification và rollout <a class="header-anchor" href="#d5-—-verification-va-rollout" aria-label="Permalink to &quot;D5 — Verification và rollout&quot;">​</a></h2><p>Test through gateway/subscription filter + provider actual G0 để kiểm unsigned denied, attachment names/range/expiry/byte identity và network no API heap video. HEAD per download là deliberate existence check, không tái dùng per-grid HEAD. Recheck parent selected WATERMARKED/RETOUCHED đúng key; file legacy converted chỉ có actual stored original. Run regress Post/Publish longer-lived signer, watermark private reads. Enable action only khi endpoint/provider/audit ready; rollback disable issuance UI/API, link cũ expiry tự nhiên, không đổi ACL policy public hoặc xóa data. Record test actual chưa chạy NOT RUN.</p>',16)])])}const g=a(o,[["render",n]]);export{p as __pageData,g as default};
